style.css:
@-moz-document domain("google.com") {
/* 1. AGGRESSIVELY HIDE ALL ORIGINAL GOOGLE LOGO ELEMENTS */
    /* This uses multiple selectors to ensure the original logo (SVG/Image/etc.) is gone */
    #logo img, #logo svg, .logo img, .logo svg, 
    #hplogo img, #hplogo svg,
    .lnXdpd, /* The specific class you found for the homepage SVG */
    .logocont, 
    .RNNXgb a:first-child img {
        display: none !important;
        visibility: hidden !important;
        width: 0 !important;
        height: 0 !important;
    }
    
    /* 2. TARGET THE MAIN LINK (HOMEPAGE & RESULTS PAGE) AND APPLY CUSTOM IMAGE ONCE */
    /* This selector is for the clickable link 'a[href="/"]' that wraps the logo */
    a[href="/"] { 
        /* Your custom image link */
        background-image: url("https://i.imgur.com/X0SroD3.png") !important; 
        
        /* Ensure the element is visible */
        display: block !important;
        
        /* Image display settings */
        background-repeat: no-repeat !important;
        background-position: center center !important; 
        background-size: contain !important; 

        /* Homepage Dimensions (Large) */
        width: 272px !important;
        min-width: 272px !important;
        height: 92px !important; 
    }
    
    /* 3. RESIZE THE RESULTS PAGE LOGO CONTAINER (ID 'logo') */
    /* This ensures the space is the correct smaller size after a search is performed */
    #logo {
        /* Results Page Dimensions (Small) */
        width: 150px !important;
        height: 50px !important;
        
        /* Must be display: block for the background image from a[href="/"] to show up */
        display: block !important;
        
        /* Ensures positioning is correct */
        margin: 0 !important;
        padding: 0 !important;
        background-image: none !important; /* Prevents double-application */
    }
}
